package com.tecsup.medico.model; import jakarta.persistence.*; import jakarta.validation.constraints.*;
@Entity @Table(name="especialidad") public class Especialidad {@Id @GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="id_especialidad")private Long id;@NotBlank @Size(max=100)@Column(nullable=false,length=100)private String nombre;@Size(max=200)private String descripcion;@Column(length=1)private String estado="A";public Long getId(){return id;}public String getNombre(){return nombre;}public void setNombre(String x){nombre=x;}public String getDescripcion(){return descripcion;}public void setDescripcion(String x){descripcion=x;}public String getEstado(){return estado;}public void setEstado(String x){estado=x;}}
